/* === ARCHITECTURAL RESPONSE VALIDATOR & ZERO-LEAKAGE GUARDRAIL === */
const ragData = $('Format RAG Knowledge Response').first()?.json || {};
const qwenItem = $input.first()?.json || {};
const qwenRaw = qwenItem.response;
const llmStatus = qwenRaw && !qwenItem.error && !qwenItem.errorMessage ? 'succeeded' : 'failed';
const llmLatencyMs = Number.isFinite(Number(qwenItem.total_duration)) ? Math.round(Number(qwenItem.total_duration) / 1000000) : null;
const locale = ragData.locale || 'ar';
const isAr = locale === 'ar';
const programScope = ragData.program_scope || 'COMMON';
const confidence = ragData.confidence || 'none';
const action = ragData.action || 'SAFE_DEFLECTION';

// 1. Direct Disambiguation Bypass
if (ragData.is_ambiguous) {
  return [{
    json: {
      status: 'clarification_required',
      intent_handled: 'faq_query',
      program: 'COMMON',
      category: 'disambiguation',
      reply: ragData.curated_answer,
      sources: ['وزارة الاتصالات وتكنولوجيا المعلومات (MCIT)'],
      validation: { status: 'passed', program_scope: 'AMBIGUOUS' },
      confidence: 'high',
      confidence_label: 'HIGH',
      guardrail_decision: 'disambiguation_prompt',
      requires_human: false,
      llm_status: 'not_needed',
      program: 'COMMON'
    }
  }];
}

// 2. Safe Deflection Text
const safeFallbackAR = 'شكراً على استفسارك. يختص نظامنا بالمعلومات المعتمدة لمبادرات وزارة الاتصالات (مبادرة الرواد الرقميون ومبادرة رواد مصر الرقمية). يمكنك زيارة البوابات الرسمية للمزيد:\n- مبادرة الرواد الرقميون: https://digilians.gov.eg\n- مبادرة رواد مصر الرقمية: https://debi.gov.eg';
const safeFallbackEN = 'Thank you for your inquiry. Our platform is specialized in MCIT initiatives (Digilians and DEBI). Please consult the official portals:\n- Digilians: https://digilians.gov.eg\n- DEBI: https://debi.gov.eg';
const safeDeflection = isAr ? safeFallbackAR : safeFallbackEN;

// 3. Evidence Gate Enforcement: If action is SAFE_DEFLECTION and confidence none
if (action === 'SAFE_DEFLECTION' && confidence === 'none') {
  return [{
    json: {
      status: 'escalation',
      intent_handled: 'faq_query',
      program: programScope,
      category: 'general',
      reply: safeDeflection,
      sources: ['وزارة الاتصالات وتكنولوجيا المعلومات (MCIT)'],
      validation: { status: 'safe_deflected', confidence: 'none' },
      confidence: 'none',
      confidence_label: 'NONE',
      guardrail_decision: 'hard_evidence_gate_deflection'
    }
  }];
}

// 4. Parse Structured Model Response
let synthesizedAnswer = '';
let isGrounded = true;

if (qwenRaw) {
  try {
    const parsed = typeof qwenRaw === 'string' ? JSON.parse(qwenRaw.trim()) : qwenRaw;
    if (parsed && parsed.answer && parsed.answer.trim()) {
      synthesizedAnswer = parsed.answer.trim();
      isGrounded = parsed.grounded !== false;
    }
  } catch (e) {
    synthesizedAnswer = qwenRaw.trim();
  }
}

// 5. Fail closed to curated answer if generation failed or returned empty
let finalReply = synthesizedAnswer;
let requiresHuman = false;
let fallbackReason = null;
let guardrailDecision = 'grounded_llm';
let responseStatus = 'success';

if (llmStatus !== 'succeeded' || !synthesizedAnswer || !isGrounded) {
  if (ragData.curated_answer && (ragData.action === 'ANSWER' || confidence === 'high' || confidence === 'medium')) {
    finalReply = ragData.curated_answer;
    guardrailDecision = 'verified_faq_fallback';
    responseStatus = 'fallback';
    fallbackReason = llmStatus !== 'succeeded' ? 'llm_generation_failed' : 'llm_answer_unavailable_or_ungrounded';
  } else {
    finalReply = safeDeflection;
    guardrailDecision = 'safe_deflection';
    responseStatus = 'escalation_required';
    requiresHuman = true;
    fallbackReason = 'insufficient_evidence';
  }
}

// Last-mile defense-in-depth sanitization
finalReply = finalReply
  .replace(/\[(?:DEBI|DIGILIANS|COMMON|GENERAL|COMPARISON)\]\s*/g, '')
  .replace(/سؤال:\s*/g, '')
  .replace(/إجابة:\s*/g, '')
  .replace(/^Q:\s*/gm, '')
  .replace(/^A:\s*/gm, '')
  .replace(/---\n?/g, '\n')
  .replace(/\*\*/g, '*')
  .replace(/^#+\s*/gm, '')
  .trim();

let sourceAttribution = 'مبادرة الرواد الرقميون (Digilians)';
if (programScope === 'DEBI') {
  sourceAttribution = 'مبادرة رواد مصر الرقمية (DEBI)';
} else if (programScope === 'COMPARISON') {
  sourceAttribution = 'مقارنة معتمدة: مبادرة الرواد الرقميون ومبادرة رواد مصر الرقمية';
} else {
  sourceAttribution = 'وزارة الاتصالات وتكنولوجيا المعلومات (MCIT)';
}

return [{
  json: {
    status: responseStatus,
    intent_handled: requiresHuman ? 'human_escalation' : 'faq_query',
    program: programScope,
    category: ragData.top_category || 'general',
    reply: finalReply,
    sources: [sourceAttribution],
    validation: {
      status: guardrailDecision === 'grounded_llm' ? 'passed' : guardrailDecision,
      confidence: confidence,
      relevance_score: ragData.relevance_score || 0,
      guardrail_decision: guardrailDecision
    },
    confidence: confidence,
    confidence_label: ragData.confidence_label || 'HIGH',
    guardrail_decision: guardrailDecision,
    llm_status: llmStatus,
    llm_latency_ms: llmLatencyMs,
    retrieved_count: ragData.matched_entries || 0,
    source_url: ragData.source_url || 'https://digilians.gov.eg',
    customer_message: ragData.customer_message || ''
  }
}];
